export function sharedWorkspace({getLocal,onLoad,onRole,onError}){
 let revision=0,ready=false,pending=0,chain=Promise.resolve(),isAdmin=false;
 async function request(method,path,body){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},cache:'no-store',...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Workspace request failed.');return d;}
 async function start(){try{if(!localStorage.getItem('frc7028-before-shared-migration'))localStorage.setItem('frc7028-before-shared-migration',JSON.stringify(getLocal()));let data=await request('GET','/api/workspace');isAdmin=data.isAdmin;onRole(isAdmin);if(!data.initialized&&isAdmin)data=await request('PUT','/api/workspace',{workspace:getLocal(),baseRevision:0});revision=data.revision;ready=true;onLoad(data.workspace);}catch(err){ready=false;onError(err.message);}}
 function save(workspace){if(!ready){onError('Wait for the shared workspace connection before saving.');return false;}pending++;const snapshot=structuredClone(workspace);chain=chain.then(async()=>{try{const d=await request('PUT','/api/workspace',{workspace:snapshot,baseRevision:revision});revision=d.revision;if(pending===1)onLoad(d.workspace);}catch(err){try{localStorage.setItem('frc7028-unsynced-backup',JSON.stringify(snapshot));}catch{}onError(err.message+' Your attempted changes were kept in a local backup.');ready=false;await start();}finally{pending--;}});return true;}
 async function review(ids,decision,reason){await chain;if(!ready||!isAdmin)throw Error('Admin access is required.');const d=await request('POST','/api/reviews',{ids,decision,reason,baseRevision:revision});revision=d.revision;onLoad(d.workspace);}
 const timer=setInterval(async()=>{if(!ready||pending||document.hidden||document.querySelector('dialog[open]'))return;try{const d=await request('GET','/api/workspace');if(d.revision!==revision){revision=d.revision;onLoad(d.workspace);}}catch{}},10000);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});
 return {start,save,review,get ready(){return ready;}};
}
